/* tarea: con 2 fotodetectores y un 7 segmentos (x4) display, hacer un contador
que cuando se accione uno de los fotodetectores, el contador aumente en 1 y cuando se
accione el otro fotodetector, el contador disminuya en 1. El contador debe mostrarse 
en el display de 7 segmentos.
*/
#include "stdint.h"
#include "stm32f411xe.h"
#include "stm32f4xx.h"

// --- VARIABLES GLOBALES ---
volatile uint16_t contador = 0; 
volatile uint8_t digitos_display[4] = {0, 0, 0, 0};
volatile uint8_t digito_actual = 0; 

static const uint8_t tabla_seg[10] = {
    0b11000000, // (A,B,C,D,E,F,_)
    0b11111001, // (_,B,C,_,_,_,_)
    0b10100100, // (A,B,_,D,E,_,G)
    0b10110000, // (A,B,C,D,_,_,G)
    0b10011001, // (_,B,C,_,_,F,G)
    0b10010010, // (A,_,C,D,_,F,G)
    0b10000010, // (A,_,_,D,E,F,G)
    0b11111000, // (_,B,C,D,E,F,G)
    0b10000000, // (A,_,_,_,E,F,G)
    0b10010000  // (A,_,C,_,_,F,G)
};


// --- PROTOTIPOS DE FUNCIONES ---
void init_GPIO(void);
void init_exti(void);
void init_timer2(void);
void init_timer3(void);

int main(void)
{
    init_GPIO();  // Configurar registros GPIO
    init_exti();  // Configurar interrupciones externas
    init_timer2(); // Configurar TIM2 y habilitar interrupciones
    init_timer3(); // Configurar TIM3 para multiplexado del displayno

    while (1) {
        digitos_display[0] = contador % 10; // unidades
        digitos_display[1] = (contador / 10) % 10; // decenas
        digitos_display[2] = (contador / 100) % 10; // centenas
        digitos_display[3] = (contador / 1000) % 10; // millares
    }
}

void init_GPIO(void) {
    // Habilitar únicamente los relojes de los puertos a usar
    RCC->AHB1ENR |= (RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIOBEN | RCC_AHB1ENR_GPIOCEN | RCC_AHB1ENR_GPIOHEN);

    // Configurar PH1 (LED)
    GPIOH->MODER &= ~(GPIO_MODER_MODE1); // Limpiar bits de modo
    GPIOH->MODER |=  (GPIO_MODER_MODE1_0); // Salida digital
    GPIOH->OTYPER &= ~GPIO_OTYPER_OT1; // Push-pull
    GPIOH->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED1); // Baja velocidad
    GPIOH->PUPDR &= ~(GPIO_PUPDR_PUPD1); // Sin Pull-up/down
    GPIOH->ODR &= ~GPIO_ODR_OD1; // Estado inicial apagado

    // Configurar los fotodetectores (PB12 y PA10) 
    GPIOB->MODER &= ~(GPIO_MODER_MODE12); // Limpiar bits, modo entrada
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD12); // Sin Pull-up/down

    GPIOA->MODER &= ~(GPIO_MODER_MODE10); // Limpiar bits, modo entrada
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD10); // Sin Pull-up/down

    // Configurar el display de 7 segmentos PA0, PA1, PA4, PB0, PB1, PB2, PB15, PC10, PC12, PC8, PC9
    // GPIOA: PA0, PA1, PA4
    GPIOA->MODER &= ~(GPIO_MODER_MODE0 | GPIO_MODER_MODE1 | GPIO_MODER_MODE4); // Limpiar bits de modo
    GPIOA->MODER |= (GPIO_MODER_MODE0_0 | GPIO_MODER_MODE1_0 | GPIO_MODER_MODE4_0); // Salida digital
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT0 | GPIO_OTYPER_OT1 | GPIO_OTYPER_OT4); // Push-pull
    GPIOA->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED0 | GPIO_OSPEEDR_OSPEED1 | GPIO_OSPEEDR_OSPEED4); // Limpiar bits de velocidad
    GPIOA->OSPEEDR |= (GPIO_OSPEEDR_OSPEED0_0 | GPIO_OSPEEDR_OSPEED1_0 | GPIO_OSPEEDR_OSPEED4_0); // Mediana velocidad
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD0 | GPIO_PUPDR_PUPD1 | GPIO_PUPDR_PUPD4); // Sin Pull-up/down

    // GPIOB: PB0, PB1, PB2, PB15
    GPIOB->MODER &= ~(GPIO_MODER_MODE0 | GPIO_MODER_MODE1 | GPIO_MODER_MODE2 | GPIO_MODER_MODE15); // Limpiar bits de modo
    GPIOB->MODER |= (GPIO_MODER_MODE0_0 | GPIO_MODER_MODE1_0 | GPIO_MODER_MODE2_0 | GPIO_MODER_MODE15_0); // Salida digital
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT0 | GPIO_OTYPER_OT1 | GPIO_OTYPER_OT2 | GPIO_OTYPER_OT15); // Push-pull
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED0 | GPIO_OSPEEDR_OSPEED1 | GPIO_OSPEEDR_OSPEED2 | GPIO_OSPEEDR_OSPEED15); // Limpiar bits de velocidad
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED0_0 | GPIO_OSPEEDR_OSPEED1_0 | GPIO_OSPEEDR_OSPEED2_0 | GPIO_OSPEEDR_OSPEED15_0); // Mediana velocidad
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD0 | GPIO_PUPDR_PUPD1 | GPIO_PUPDR_PUPD2 | GPIO_PUPDR_PUPD15); // Sin Pull-up/down

    // GPIOC: PC10, PC12, PC8, PC9
    GPIOC->MODER &= ~(GPIO_MODER_MODE10 | GPIO_MODER_MODE12 | GPIO_MODER_MODE8 | GPIO_MODER_MODE9); // Limpiar bits de modo
    GPIOC->MODER |= (GPIO_MODER_MODE10_0 | GPIO_MODER_MODE12_0 | GPIO_MODER_MODE8_0 | GPIO_MODER_MODE9_0); // Salida digital
    GPIOC->OTYPER &= ~(GPIO_OTYPER_OT10 | GPIO_OTYPER_OT12 | GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9); // Push-pull
    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED10 | GPIO_OSPEEDR_OSPEED12 | GPIO_OSPEEDR_OSPEED8 | GPIO_OSPEEDR_OSPEED9); // Limpiar bits de velocidad
    GPIOC->OSPEEDR |= (GPIO_OSPEEDR_OSPEED10_0 | GPIO_OSPEEDR_OSPEED12_0 | GPIO_OSPEEDR_OSPEED8_0 | GPIO_OSPEEDR_OSPEED9_0); // Mediana velocidad
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD10 | GPIO_PUPDR_PUPD12 | GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9); // Sin Pull-up/down

    // Configurar los pines de control del display (PB14, PC2, PB13, PC3)
    // GPIOB: PB13, PB14
    GPIOB->MODER &= ~(GPIO_MODER_MODE0 | GPIO_MODER_MODE1 | GPIO_MODER_MODE2 | GPIO_MODER_MODE13 | GPIO_MODER_MODE14 | GPIO_MODER_MODE15);
    GPIOB->MODER |=  (GPIO_MODER_MODE0_0 | GPIO_MODER_MODE1_0 | GPIO_MODER_MODE2_0 | GPIO_MODER_MODE13_0 | GPIO_MODER_MODE14_0 | GPIO_MODER_MODE15_0); 
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT0 | GPIO_OTYPER_OT1 | GPIO_OTYPER_OT2 | GPIO_OTYPER_OT13 | GPIO_OTYPER_OT14 | GPIO_OTYPER_OT15); 
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED0_0 | GPIO_OSPEEDR_OSPEED1_0 | GPIO_OSPEEDR_OSPEED2_0 | GPIO_OSPEEDR_OSPEED13_0 | GPIO_OSPEEDR_OSPEED14_0 | GPIO_OSPEEDR_OSPEED15_0); 
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD0 | GPIO_PUPDR_PUPD1 | GPIO_PUPDR_PUPD2 | GPIO_PUPDR_PUPD13 | GPIO_PUPDR_PUPD14 | GPIO_PUPDR_PUPD15);
    // GPIOC: PC2, PC3
    GPIOC->MODER &= ~(GPIO_MODER_MODE2 | GPIO_MODER_MODE3); 
    GPIOC->MODER |=  (GPIO_MODER_MODE2_0 | GPIO_MODER_MODE3_0); 
    GPIOC->OTYPER &= ~(GPIO_OTYPER_OT2 | GPIO_OTYPER_OT3); 
    GPIOC->OSPEEDR |= (GPIO_OSPEEDR_OSPEED2_0 | GPIO_OSPEEDR_OSPEED3_0); 
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD2 | GPIO_PUPDR_PUPD3);
}

void init_exti(void) { // interrupciones externas para PB12 y PA10
    // Habilitar el reloj del SYSCFG
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; //Habilitar reloj del SYSCFG

    // Congiguración de EXTI10 (PA10)
    SYSCFG->EXTICR[2] &= ~SYSCFG_EXTICR3_EXTI10_Msk; // Limpiar bits EXTI10
    SYSCFG->EXTICR[2] |= SYSCFG_EXTICR3_EXTI10_PA; // Configurar EXTI10 para PA10

    // Configuración de EXTI12 (PB12)
    SYSCFG->EXTICR[3] &= ~SYSCFG_EXTICR4_EXTI12_Msk; // Limpiar bits EXTI12
    SYSCFG->EXTICR[3] |= SYSCFG_EXTICR4_EXTI12_PB; // Configurar EXTI12 para PB12

    // Habilirar las mascaras y interrupciones por flanco de subida
    EXTI->IMR |= (EXTI_IMR_IM10 | EXTI_IMR_IM12); // Habilitar interrupciones para EXTI10 y EXTI12
    EXTI->RTSR |= (EXTI_RTSR_TR10 | EXTI_RTSR_TR12); // Habilitar flanco de subida para EXTI10 y EXTI12
    
    // Habilitar las interrupciones en el NVIC
    NVIC_EnableIRQ(EXTI15_10_IRQn); // Habilitar interrupciones
}

void init_timer2(void) { // led blink cada 500 ms
    // Reloj base APB1 = 16 MHz por defecto (HSI)
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN; 

    TIM2->PSC = 16000 - 1; // F_timer = 16MHz / 16000 = 1 kHz (Pasos de 1 ms)
    TIM2->ARR = 500 - 1;   // Interrupción cada 500 ms (0.5 segundos)
    TIM2->CNT = 0;

    TIM2->DIER |= TIM_DIER_UIE;   // Habilitar interrupción de actualización
    TIM2->CR1 &= ~TIM_CR1_DIR;    // Modo ascendente
    TIM2->CR1 |= TIM_CR1_ARPE;    // Auto-reload preload enable

    TIM2->SR &= ~TIM_SR_UIF;      // Limpiar bandera pendiente previo a arrancar
    NVIC_EnableIRQ(TIM2_IRQn);    // Activar línea de interrupción en NVIC
    TIM2->CR1 |= TIM_CR1_CEN;     // Iniciar contador
}

void init_timer3(void) { // Timer3 para multiplexado del display
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN; // Habilitar reloj de TIM3

    TIM3->PSC = 16000 - 1; // F_timer = 16MHz / 16000 = 1 kHz (Pasos de 1 ms)
    TIM3->ARR = 5 - 1;     // Interrupción cada 5 ms
    TIM3->CNT = 0;

    TIM3->DIER |= TIM_DIER_UIE;   // Habilitar interrupción de actualización
    TIM3->CR1 &= ~TIM_CR1_DIR;    // Modo ascendente
    TIM3->CR1 |= TIM_CR1_ARPE;    // Auto-reload preload enable

    TIM3->SR &= ~TIM_SR_UIF;      // Limpiar bandera pendiente previo a arrancar
    NVIC_EnableIRQ(TIM3_IRQn);    // Activar línea de interrupción en NVIC
    TIM3->CR1 |= TIM_CR1_CEN;     // Iniciar contador
}

void TIM3_IRQHandler(void) {
    TIM3->SR &= ~TIM_SR_UIF; // Limpiar bandera

    // 1. Apagar transistores para evitar ghosting
    GPIOB->BSRR = (GPIO_BSRR_BR13 | GPIO_BSRR_BR14);
    GPIOC->BSRR = (GPIO_BSRR_BR2  | GPIO_BSRR_BR3);
    // 2. Obtener el patrón del dígito actual
    uint8_t patron = tabla_seg[digitos_display[digito_actual]];

    // Mapeo de segmentos GPIOA (C: PA1 | D: PA4 | G: PA0)
    GPIOA->BSRR = ((patron & (1 << 2)) ? GPIO_BSRR_BS1 : GPIO_BSRR_BR1) |
                  ((patron & (1 << 3)) ? GPIO_BSRR_BS4 : GPIO_BSRR_BR4) |
                  ((patron & (1 << 6)) ? GPIO_BSRR_BS0 : GPIO_BSRR_BR0);

    // Mapeo de segmentos GPIOB (A: PB15 | B: PB2 | E: PB0 | F: PB1)
    GPIOB->BSRR = ((patron & (1 << 0)) ? GPIO_BSRR_BS15 : GPIO_BSRR_BR15) |
                  ((patron & (1 << 1)) ? GPIO_BSRR_BS2  : GPIO_BSRR_BR2)  |
                  ((patron & (1 << 4)) ? GPIO_BSRR_BS0  : GPIO_BSRR_BR0)  |
                  ((patron & (1 << 5)) ? GPIO_BSRR_BS1  : GPIO_BSRR_BR1);

    // 3. Mapeo corregido según el resultado del diagnóstico 4321
    switch (digito_actual) {
        case 0: GPIOC->BSRR = GPIO_BSRR_BS3;  break; // Unidades  -> PC3
        case 1: GPIOB->BSRR = GPIO_BSRR_BS13; break; // Decenas   -> PB13
        case 2: GPIOC->BSRR = GPIO_BSRR_BS2;  break; // Centenas  -> PC2
        case 3: GPIOB->BSRR = GPIO_BSRR_BS14; break; // Miles     -> PB14
    }

    // 4. Barrido ascendente
    digito_actual = (digito_actual + 1) & 0x03;
}

void EXTI15_10_IRQHandler(void) {    // Manejador de interrupción para EXTI11 y EXTI12
    if (EXTI->PR & EXTI_PR_PR10) { // Interrupción por PA10
        EXTI->PR |= EXTI_PR_PR10; // Limpiar 
        contador--; // Decrementar contador
    }
    if (EXTI->PR & EXTI_PR_PR12) { // Interrupción por PB12
        EXTI->PR |= EXTI_PR_PR12; // Limpiar bandera escribiendo 1 en bit PR12
        contador++; // Incrementar contador 
    }
}

void TIM2_IRQHandler(void) {    // Blinking del LED en PH1 cada 500 ms
    if (TIM2->SR & TIM_SR_UIF) { 
        TIM2->SR &= ~TIM_SR_UIF; // Limpiar la bandera escribiendo 0 en bit UIF

        GPIOH->ODR ^= GPIO_ODR_OD1; // Alternar el estado del LED en PH1
    }
}